using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TechnifyERP.Application.Badges;
namespace TechnifyERP.Areas.Admin.Controllers;[Area("Admin"),Authorize(Roles="SuperAdmin")]public sealed class BadgesController(IBadgeService service):Controller{public async Task<IActionResult>Index(CancellationToken ct)=>View(await service.GetAllAsync(ct));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(string name,string description,CancellationToken ct){var r=await service.CreateAsync(name,description,null,ct);TempData[r==BadgeActionResult.Success?"SuccessMessage":"ErrorMessage"]=r==BadgeActionResult.Success?"Badge create ho gaya.":"Badge name unique aur details required hain.";return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id,CancellationToken ct){await service.DeleteAsync(id,ct);return RedirectToAction(nameof(Index));}}
